                self.regs[addr] = 0x399F  # Reset to default value
            else:
                # Mask out RST bit and keep other bits
                self.regs[addr] = (self.regs[addr] & ~(1 << 15)) | (data & 0x7FFF)

        elif addr == 0x05:  # CALIBRATION
            # FS0 bit is a void bit and should always be 0
            data &= 0xFFFE

        if nbytes == 1:
            # Update only bits 15:8
            self.regs[addr] = (self.regs[addr] & 0x00FF) | ((data << 8) & 0xFF00)
        elif nbytes == 2:
            self.regs[addr] = data
        else:
            raise ValueError("nbytes must be 1 or 2")
